code_sketch:
args := amqp.Table{"x-dead-letter-exchange": "dlx", "x-dead-letter-routing-key": "failed"}
ch.QueueDeclare("orders", true, false, false, false, args)
deliveries, _ := ch.Consume("orders", "", false, false, false, false, nil)
for d := range deliveries {
    if err := handle(d.Body); err != nil && isPermanent(err) {
        d.Nack(false, false)        // requeue=false -> broker dead-letters
    } else if err != nil {
        d.Nack(false, true)         // transient -> requeue (with a retry policy)
    } else {
        d.Ack(false)
    }
}

