var adv struct {
    Stream    string `json:"stream"`
    Consumer  string `json:"consumer"`
    StreamSeq uint64 `json:"stream_seq"`
}
nc.Subscribe("$JS.EVENT.ADVISORY.CONSUMER.MAX_DELIVERIES.ORDERS.shipping",
    func(m *nats.Msg) {
        if json.Unmarshal(m.Data, &adv) != nil { return }
        raw, err := js.GetMsg(adv.Stream, adv.StreamSeq)
        if err != nil { return }   // core NATS has no replay: reconcile from stream state
        js.Publish("DLQ.ORDERS", raw.Data,
            jetstream.WithMsgID(fmt.Sprint(adv.StreamSeq)))
    })
